@code {
    [Parameter, EditorRequired] public WorkHistory WorkHistory { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<WorkHistory> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkHistory> OnBack { get; set; }

    private List<WorkEntryModel> Entries { get; set; } = new();
    private string? ValidationError { get; set; }

    protected override void OnParametersSet()
    {
        if (WorkHistory.Entries.Count > 0)
        {
            Entries = WorkHistory.Entries.Select(e =>
                new WorkEntryModel(e.Company, e.Title, e.StartDate, e.EndDate, e.Description, e.EndDate is null)).ToList();
        }
        else if (Entries.Count == 0)
        {
            Entries = new() { EmptyEntry() };
        }
    }

    private void AddEntry() => Entries.Add(EmptyEntry());
    private void RemoveEntry(int index) => Entries.RemoveAt(index);
    private void UpdateEntry(int index, WorkEntryModel updated) => Entries[index] = updated;

    private WorkHistory ToWorkHistory() =>
        new(Entries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());

    private async Task HandleNext()
    {
        ValidationError = null;
        foreach (var e in Entries)
        {
            if (string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title))
            {
                ValidationError = "Each position must have a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync(ToWorkHistory());
    }

    private async Task HandleBack() => await OnBack.InvokeAsync(ToWorkHistory());

    private static WorkEntryModel EmptyEntry() => new(string.Empty, string.Empty, DateTime.Today, null, string.Empty, false);
}
