@namespace sv_77ed9ae69af14bf796cce197554c655a.Components.Pages.Apply

<h4>Cover Letter</h4>

<div class="mb-3">
    <textarea class="form-control" rows="12" maxlength="@MaxLength"
              value="@CoverLetter"
              @oninput="HandleInput"></textarea>
    <div class="form-text text-end">
        @(CoverLetter?.Length ?? 0) / @MaxLength characters
    </div>
</div>

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="alert alert-danger">@ValidationError</div>
}

<div class="d-flex justify-content-between">
    <button type="button" class="btn btn-secondary" @onclick="HandleBack">Back</button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnBack { get; set; }

    private const int MaxLength = 2000;
    private string? ValidationError { get; set; }

    private void HandleInput(ChangeEventArgs e)
    {
        CoverLetter = e.Value?.ToString() ?? string.Empty;
        if (CoverLetter.Length > MaxLength)
            CoverLetter = CoverLetter[..MaxLength];
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ValidationError = "Please provide a cover letter.";
            return;
        }
        await OnNext.InvokeAsync(CoverLetter);
    }

    private async Task HandleBack() => await OnBack.InvokeAsync(CoverLetter);
}

