@namespace sv_77ed9ae69af14bf796cce197554c655a.Components.Pages.Apply
@using sv_77ed9ae69af14bf796cce197554c655a.Models

<h4>Review Your Application</h4>

@if (!string.IsNullOrEmpty(SubmissionError))
{
    <div class="alert alert-danger">@SubmissionError</div>
}

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Personal Information</strong>
        <button type="button" class="btn btn-sm btn-link" @onclick='() => OnEditStep.InvokeAsync(0)'>Edit</button>
    </div>
    <div class="card-body">
        <dl class="row mb-0">
            <dt class="col-sm-3">Name</dt>
            <dd class="col-sm-9">@Personal.FullName</dd>
            <dt class="col-sm-3">Email</dt>
            <dd class="col-sm-9">@Personal.Email</dd>
            <dt class="col-sm-3">Phone</dt>
            <dd class="col-sm-9">@Personal.Phone</dd>
            <dt class="col-sm-3">Address</dt>
            <dd class="col-sm-9">@Personal.Address</dd>
        </dl>
    </div>
</div>

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Work History</strong>
        <button type="button" class="btn btn-sm btn-link" @onclick='() => OnEditStep.InvokeAsync(1)'>Edit</button>
    </div>
    <div class="card-body">
        @foreach (var entry in Work.Entries)
        {
            <div class="mb-3">
                <strong>@entry.Title</strong> at @entry.Company<br />
                <small class="text-muted">
                    @entry.StartDate.ToString("MMM yyyy") &ndash;
                    @(entry.EndDate.HasValue ? entry.EndDate.Value.ToString("MMM yyyy") : "Present")
                </small>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p class="mt-1 mb-0">@entry.Description</p>
                }
            </div>
        }
    </div>
</div>

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>References</strong>
        <button type="button" class="btn btn-sm btn-link" @onclick='() => OnEditStep.InvokeAsync(2)'>Edit</button>
    </div>
    <div class="card-body">
        @foreach (var r in References)
        {
            <div class="mb-2">
                <strong>@r.Name</strong> — @r.Relationship<br />
                <small>@r.Email | @r.Phone</small>
            </div>
        }
    </div>
</div>

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Cover Letter</strong>
        <button type="button" class="btn btn-sm btn-link" @onclick='() => OnEditStep.InvokeAsync(3)'>Edit</button>
    </div>
    <div class="card-body">
        <p style="white-space: pre-wrap;">@CoverLetter</p>
    </div>
</div>

<div class="d-flex justify-content-between">
    <button type="button" class="btn btn-secondary" @onclick="() => OnEditStep.InvokeAsync(3)">Back</button>
    <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
        @if (IsSubmitting)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
        }
        Submit Application
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Personal { get; set; } = default!;
    [Parameter, EditorRequired] public WorkHistory Work { get; set; } = default!;
    [Parameter, EditorRequired] public List<Reference> References { get; set; } = new();
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter, EditorRequired] public EventCallback OnSubmit { get; set; }

    private bool IsSubmitting { get; set; }
    private string? SubmissionError { get; set; }

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        SubmissionError = null;
        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
        {
            SubmissionError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

