@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (SubmittedApplicationId.HasValue)
    {
        <div class="alert alert-success text-center">
            <h4 class="alert-heading">Application Submitted!</h4>
            <p>Your application has been received. Your application ID is:</p>
            <p class="display-6 fw-bold">@SubmittedApplicationId</p>
            <hr />
            <p class="mb-0">We'll be in touch soon.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="@CurrentStep"
                       CompletedSteps="@CompletedSteps"
                       OnStepClicked="GoToStep" />

        @switch (CurrentStep)
        {
            case 0:
                <PersonalInfoStep PersonalInfo="@Personal"
                                  ApplicationService="@ApplicationService"
                                  OnNext="HandlePersonalNext" />
                break;
            case 1:
                <WorkHistoryStep WorkHistory="@Work"
                                 OnNext="HandleWorkNext"
                                 OnBack="HandleWorkBack" />
                break;
            case 2:
                <ReferencesStep References="@References"
                                OnNext="HandleReferencesNext"
                                OnBack="HandleReferencesBack" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@CoverLetter"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="HandleCoverLetterBack" />
                break;
            case 4:
                <ReviewStep Personal="@Personal"
                            Work="@Work"
                            References="@References"
                            CoverLetter="@CoverLetter"
                            OnEditStep="GoToStep"
                            OnSubmit="HandleSubmit" />
                break;
        }
    }
</div>

@code {
    private int CurrentStep { get; set; }
    private HashSet<int> CompletedSteps { get; set; } = new();
    private int? SubmittedApplicationId { get; set; }

    // Form state
    private PersonalInfo Personal { get; set; } = new(string.Empty, string.Empty, string.Empty, string.Empty);
    private WorkHistory Work { get; set; } = new(new List<WorkEntry>());
    private List<Reference> References { get; set; } = new();
    private string CoverLetter { get; set; } = string.Empty;

    private void GoToStep(int step)
    {
        if (step <= CurrentStep || CompletedSteps.Contains(step))
            CurrentStep = step;
    }

    private void HandlePersonalNext(PersonalInfo info)
    {
        Personal = info;
        CompletedSteps.Add(0);
        CurrentStep = 1;
    }

    private void HandleWorkNext(WorkHistory work)
    {
        Work = work;
        CompletedSteps.Add(1);
        CurrentStep = 2;
    }

    private void HandleWorkBack(WorkHistory work)
    {
        Work = work;
        CurrentStep = 0;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        References = refs;
        CompletedSteps.Add(2);
        CurrentStep = 3;
    }

    private void HandleReferencesBack(List<Reference> refs)
    {
        References = refs;
        CurrentStep = 1;
    }

    private void HandleCoverLetterNext(string letter)
    {
        CoverLetter = letter;
        CompletedSteps.Add(3);
        CurrentStep = 4;
    }

    private void HandleCoverLetterBack(string letter)
    {
        CoverLetter = letter;
        CurrentStep = 2;
    }

    private async Task HandleSubmit()
    {
        var application = new JobApplication(Personal, Work, References, CoverLetter);
        var id = await ApplicationService.SubmitApplicationAsync(application);
        SubmittedApplicationId = id;
    }
}

